import { serializeCube } from '@/lut';
import { bakeRecipe, type Bakeable, type LutResolver } from './bake';

/**
 * Exports the recipe's colour stack as `.cube` text (3D, sRGB-encoded in and out, the same data the
 * preview uses). Grain and vignette are spatial effects and cannot be part of a LUT.
 */
export function recipeToCube(recipe: Bakeable, resolve: LutResolver, size = 33): string {
  const { lut, warnings } = bakeRecipe(recipe, resolve, size);
  return serializeCube(lut, {
    title: recipe.name,
    comments: [
      'Generated by LUT Studio',
      'Input and output are sRGB-encoded, domain 0..1.',
      'Grain and vignette are not included in this LUT.',
      ...warnings.map((w) => `Warning: ${w.message}`),
    ],
  });
}
